create temp table qa_results(name text primary key,ok boolean not null);
create function pg_temp.qa(ok boolean,label text) returns void language plpgsql as $$ begin
 if ok is distinct from true then raise exception 'QA FAILED: %',label;end if;insert into qa_results values(label,true);end $$;
create function pg_temp.denied(command text,expected text,label text) returns void language plpgsql as $$ begin
 begin execute command;exception when others then
  if sqlerrm=expected then perform pg_temp.qa(true,label);return;end if;
  raise exception 'QA unexpected error for %: %',label,sqlerrm;
 end;raise exception 'QA unexpectedly allowed: %',label;end $$;
do $$ declare a uuid:=(select id from qa_people where slot=1);b uuid:=(select id from qa_people where slot=2);c uuid:=(select id from qa_people where slot=3);
 j jsonb;d record;mid uuid;r uuid;deck text;v integer;
begin
 perform set_config('request.jwt.claim.sub',a::text,true);j:=public.aamix_inventory();
 perform pg_temp.qa(jsonb_array_length(j->'missions')=13,'Four visible missions added without replacing nine existing');
 perform pg_temp.qa(not exists(select 1 from jsonb_array_elements(j->'missions') m where m->>'id' in('challenge_complete','challenge_maagover','challenge_girabl','collect_all_standard')),'Unmet secret missions never listed');
 perform pg_temp.qa(j->'achievement_notifications'='[]','Unmet secret missions never notified');
 perform pg_temp.denied('select public.aamix_set_avatar(''0114'')','AAMIX_AVATAR_LOCKED','Sam portrait locked before mission');
 perform pg_temp.denied('select public.aamix_set_avatar(''01a'')','AAMIX_AVATAR_LOCKED','Peri portrait locked before gift entitlement');
 perform pg_temp.denied('select public.aamix_set_avatar(''01c'')','AAMIX_AVATAR_LOCKED','Other promotional portraits remain locked');
 perform pg_temp.denied('select public.aamix_claim_mission(''collect_ten_sam'')','AAMIX_MISSION_INCOMPLETE','Cannot claim incomplete photo mission');
 insert into public.aamix_collection values(a,'0114',9);
 perform pg_temp.qa((select (m->>'progress')::integer=9 from jsonb_array_elements(public.aamix_inventory()->'missions') m where m->>'id'='collect_ten_sam'),'Nine copies do not complete mission');
 update public.aamix_collection set quantity=10 where user_id=a and code='0114';
 update public.aamix_collection set quantity=9 where user_id=a and code='0114';
 perform pg_temp.qa((select (m->>'progress')::integer=10 and not (m->>'claimed')::boolean from jsonb_array_elements(public.aamix_inventory()->'missions') m where m->>'id'='collect_ten_sam'),'Ten-copy threshold stays completed after losing a copy before claim');
 j:=public.aamix_claim_mission('collect_ten_sam');perform pg_temp.qa(j->>'reward_avatar'='0114' and j->'available_avatar_codes' @> '["0114"]','Claim unlocks Sam photo permanently');
 j:=public.aamix_claim_mission('collect_ten_sam');perform pg_temp.qa((j->>'already_claimed')::boolean and (select count(*)=1 from aamix_private.avatar_unlocks_v170 where user_id=a and code='0114'),'Photo claim retry cannot duplicate');
 delete from public.aamix_collection where user_id=a and code='0114';j:=public.aamix_set_avatar('0114');
 perform pg_temp.qa(j->'profile'->>'avatar_code'='0114','Earned portrait remains usable without owning copies');
 for d in select id,card_code from aamix_private.milestone_definitions_v170 where not secret and id<>'collect_ten_sam' loop
  insert into public.aamix_collection values(a,d.card_code,10);perform public.aamix_claim_mission(d.id);delete from public.aamix_collection where user_id=a and code=d.card_code;
 end loop;
 perform pg_temp.qa((select count(*)=4 from aamix_private.avatar_unlocks_v170 where user_id=a),'Yuri Celia Sam and Viborin all use permanent mission entitlements');
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform pg_temp.denied('select public.aamix_set_avatar(''0114'')','AAMIX_AVATAR_LOCKED','Another UUID cannot use earned portrait');
 j:=public.aamix_redeem_code(' b1gote5 ');
 perform pg_temp.qa(j->>'reward_avatar'='01b' and (j->'collection'->>'01b')::integer=3,'Requested Bigotes alias grants original cards and portrait');
 j:=public.aamix_redeem_code('B1G0T3S');perform pg_temp.qa((j->>'already_redeemed')::boolean and (j->'collection'->>'01b')::integer=3,'Canonical Bigotes spelling shares the same redemption');
 j:=public.aamix_redeem_code('P3R1');perform pg_temp.qa(j->>'reward_avatar'='01a' and (j->'collection'->>'01a')::integer=3,'Requested Peri alias grants original cards and portrait');
 j:=public.aamix_redeem_code('P3RI');perform pg_temp.qa((j->>'already_redeemed')::boolean and (j->'collection'->>'01a')::integer=3,'Canonical Peri spelling cannot duplicate alias reward');
 perform public.aamix_set_avatar('01b');j:=public.aamix_set_avatar('01a');perform pg_temp.qa(j->'profile'->>'avatar_code'='01a','Only entitled promotional photos can be selected');
 perform pg_temp.qa(aamix_private.trade_family('01a') is null and aamix_private.trade_family('01b') is null,'Promotional photo exception never permits trading promotional cards');
 perform set_config('request.jwt.claim.sub',c::text,true);j:=public.aamix_inventory();
 perform pg_temp.qa(j->'available_avatar_codes' @> '["01b"]' and (j->'collection'->>'01b')::integer=3,'Earlier canonical redemption backfilled portrait without extra cards');
 perform pg_temp.qa(j->'profile'->>'avatar_code'='','Previously selected newly locked photo falls back to default');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform pg_temp.denied('select public.aamix_save_custom_deck(gen_random_uuid(),'''',''Locked'',''custom_maagover'',''[{"codigo":"0100","cantidad":40}]'',false,0)','AAMIX_DECK_COVER_LOCKED','New challenge cover cannot be forged');
 for d in select value x from jsonb_array_elements(aamix_private.challenge_definitions()) loop
  insert into public.aamix_match_receipts(user_id,request_id,deck_id,challenge_stage,challenge_opponent) values(a,gen_random_uuid(),'kajido',(d.x->>'stage')::smallint,jsonb_build_object('id',d.x->>'deck_id','cartas',(select cards from aamix_private.base_decks where id=d.x->>'deck_id'))) returning match_id into mid;
  j:=public.aamix_finish_match(mid,'victory');
  if (d.x->>'stage')::integer=4 then
   perform pg_temp.qa(j->'available_custom_covers' @> '["custom_maagover"]' and not (j->'available_custom_covers' @> '["custom_girabl"]'),'Maagover victory grants only its challenge cover');
  end if;
 end loop;
 perform pg_temp.qa((j->'collection'->>'01d')::integer=1 and j->'available_custom_covers' @> '["custom_maagover","custom_girabl"]','Full challenge awards one Granjita and both earned covers');
 perform pg_temp.qa((j->>'packs')::integer=8,'Original challenge pack rewards remain unchanged');
 j:=public.aamix_finish_match(mid,'victory');perform pg_temp.qa((j->'collection'->>'01d')::integer=1 and (j->>'packs')::integer=8,'Repeated match receipt cannot repeat secret rewards');
 perform pg_temp.qa(jsonb_array_length(j->'achievement_notifications')=3,'Only completed secret rewards enter durable notice outbox');
 insert into public.aamix_collection values(a,'0100',40);
 j:=public.aamix_save_custom_deck(gen_random_uuid(),'','Earned','custom_maagover','[{"codigo":"0100","cantidad":40}]',false,0);deck:=j->'last_saved_deck'->>'id';
 j:=public.aamix_save_custom_deck(gen_random_uuid(),deck,'Earned','custom_girabl','[{"codigo":"0100","cantidad":40}]',false,1);
 perform pg_temp.qa(j->'last_saved_deck'->>'portada'='custom_girabl','Both earned covers work in create and edit');
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform pg_temp.denied('select public.aamix_ack_achievement(''challenge_complete'')','AAMIX_REWARD_UNAVAILABLE','Other UUID cannot acknowledge secret reward');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.aamix_ack_achievement('challenge_complete');perform public.aamix_ack_achievement('challenge_maagover');j:=public.aamix_ack_achievement('challenge_girabl');
 perform pg_temp.qa(j->'achievement_notifications'='[]','Acknowledged secret rewards do not appear again');
 insert into public.aamix_collection(user_id,code,quantity) select a,code,1 from aamix_private.reward_catalog where not is_promotional and code<>'0101'
 on conflict(user_id,code) do update set quantity=greatest(public.aamix_collection.quantity,excluded.quantity);
 perform pg_temp.qa(not exists(select 1 from public.aamix_collection where user_id=a and code='01f'),'One missing standard card blocks full collection reward');
 insert into public.aamix_collection values(a,'0101',1);j:=public.aamix_inventory();
 perform pg_temp.qa((j->'collection'->>'01f')::integer=1 and jsonb_array_length(j->'achievement_notifications')=1,'All non-promotional cards award exactly one Almas Perdidas');
 delete from public.aamix_collection where user_id=a and code='0101';insert into public.aamix_collection values(a,'0101',1);
 perform pg_temp.qa((select quantity=1 from public.aamix_collection where user_id=a and code='01f'),'Losing and regaining full collection cannot repeat reward');
 perform public.aamix_ack_achievement('collect_all_standard');j:=public.aamix_ack_achievement('collect_all_standard');
 perform pg_temp.qa(j->'achievement_notifications'='[]','Notification acknowledgement is idempotent');
 perform pg_temp.qa(jsonb_array_length(j->'missions')=13 and not exists(select 1 from jsonb_array_elements(j->'missions') m where m->>'id' like 'challenge_%'),'Secret missions stay absent even after completion');
 insert into public.aamix_collection values(b,'0104',1);
 insert into aamix_private.friendships(low_id,high_id,sender,status) values(least(a,b),greatest(a,b),a,'accepted');
 j:=public.aamix_trade_room_create(b,gen_random_uuid());r:=(j->'trade_room'->>'id')::uuid;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.aamix_trade_room_action(r,'accept','',1,gen_random_uuid());
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.aamix_trade_room_action(r,'offer','0101',2,gen_random_uuid());
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.aamix_trade_room_action(r,'offer','0104',3,gen_random_uuid());
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.aamix_trade_room_action(r,'confirm','',4,gen_random_uuid());
 perform set_config('request.jwt.claim.sub',b::text,true);j:=public.aamix_trade_room_action(r,'confirm','',4,gen_random_uuid());
 perform pg_temp.qa(j->'trade_notifications'->0->>'code'='0101','Guest receives only own incoming card notification');
 perform set_config('request.jwt.claim.sub',c::text,true);
 perform pg_temp.denied(format('select public.aamix_ack_trade(%L,gen_random_uuid())',r),'AAMIX_TRADE_UNAVAILABLE','Third UUID cannot acknowledge a trade');
 perform set_config('request.jwt.claim.sub',a::text,true);j:=public.aamix_social_sync();
 perform pg_temp.qa(j->'trade_notifications'->0->>'code'='0104','Host receives its own incoming card notification');
 j:=public.aamix_ack_trade(r,gen_random_uuid());perform public.aamix_ack_trade(r,gen_random_uuid());
 perform pg_temp.qa(j->'trade_notifications'='[]' and (select status='completed' from aamix_private.trade_rooms_v160 where id=r),'Acknowledgement removes notice while preserving transaction integrity');
 perform set_config('request.jwt.claim.sub',b::text,true);j:=public.aamix_social_sync();
 perform pg_temp.qa(jsonb_array_length(j->'trade_notifications')=1,'Peer must acknowledge its own notice independently');
 perform public.aamix_ack_trade(r,gen_random_uuid());
 perform pg_temp.qa(not has_function_privilege('anon','public.aamix_ack_achievement(text)','execute') and not has_function_privilege('anon','public.aamix_ack_trade(uuid,uuid)','execute'),'Anonymous notification RPCs denied');
 perform pg_temp.qa(not has_function_privilege('authenticated','aamix_private.grant_milestone_v170(uuid,text)','execute') and not has_function_privilege('authenticated','aamix_private.complete_milestone_v170(uuid,text)','execute'),'Authenticated clients cannot self-grant achievements');
 perform pg_temp.qa(not has_table_privilege('authenticated','aamix_private.avatar_unlocks_v170','insert') and not has_table_privilege('authenticated','aamix_private.milestones_v170','update'),'Direct entitlement and completion writes denied');
end $$;
select count(*) checks,bool_and(ok) passed,jsonb_agg(name order by name) cases from qa_results;
